server.tool("kinemesh_skeleton", "骨架识别与映射（本地只读）：产出 skeleton-report.json（每骨名称/层级/rest 世界坐标/partGuess/置信、convention 约定识别、映射覆盖统计、未映射清单、结构统计、标注截图批次与映射文件 schema 尾注），返回内联 digest + 两级兜底指引。shots:auto（缺省，CORE15 有缺口才出）/ all 直接渲染骨骼名标注截图 labels-<view>-<两位批次>.png（front/side × 每批，B.4 stride 分批防叠；缺 playwright 时降级只出 report 并给安装指引）。标准命名 rig（Mixamo/Biped/UE/VRM/Rigify）字典查表直达；非标命名回退 AI 流程：读 report →（不透明再读标注截图）→ 写 kinemesh-bones.json → 重跑 analyze 即确定性消费。工具只做字典查表与约定识别。", {
	path: string().describe("模型文件路径（绝对路径，或相对客户端进程工作目录；支持 ~ 开头）"),
	shots: _enum([
		"auto",
		"none",
		"all"
	]).optional().describe("标注截图批次：auto（缺省，CORE15 有缺口才出）/ none（只出 report）/ all（强制全量批次）"),
	boneMap: string().optional().describe("骨架映射文件路径（kinemesh-bones.json）；缺省按 资产同目录 > 工作区 发现"),
	out: string().optional().describe("中间文件输出目录；缺省 <当前工作目录>/.kinemeshtmp/run-<时间戳>-<pid>/")
}, async ({ path: rawPath, shots, boneMap, out }) => {
	try {
		const loaded = await readModelFile(rawPath);
		const result = await runSkeleton(loaded.data, path.basename(loaded.abs), {
			shots,
			boneMap: boneMap === void 0 ? void 0 : expandHome(boneMap),
			out: out === void 0 ? void 0 : expandHome(out)
		}, {
			assetDir: path.dirname(loaded.abs),
			absPath: loaded.abs
		});
		return { content: [{
			type: "text",
			text: JSON.stringify(result, null, 2)
		}] };
	} catch (error) {
		return errorResult(error, `识别 ${rawPath} 的骨架`);
	}
});
server.tool("kinemesh_render", "按视角 + 帧号渲染模型截图，PNG 落盘返回绝对路径数组（再用读图工具逐张查看）。视角二选一：view（完整球坐标对象）或 viewPreset（front/side/back/three-quarter/orbit8）；渲染模式 default / solid / wireframe / skeleton / bones-overlay，**省略 mode 时按模型自动选**（无 mesh→skeleton；贴图解不出来→solid；有可用贴图→default）。**只给 viewPreset 时逐帧按身体包围盒自动取景**（带 root motion 的动作不会跑出画面；显式给 view 则按指定构图）。boneLabels 在 skeleton / bones-overlay 模式下给截图画骨骼名文字标签（B.4：auto 第 1 批 | 批次号 | all，骨架识别读图用）。**动作文件不带 mesh 时**：mesh 参数给独立网格文件（自动识别角色、按骨骼名绑定，部分骨骼动作也可）；不传时按文件内容（骨骼覆盖率）自动识别同资产网格文件。截屏构图与 DSH「动析」预览面板一致。", {
	path: string().describe("模型文件路径"),
	mesh: string().optional().describe("独立 mesh 文件路径（可选）：动作文件只有动画没有网格时，用它的网格做渲染主体、动画按骨骼名自动绑定；不传时按文件内容（骨骼覆盖率）自动识别同资产网格文件"),
	clip: string().optional().describe("动画片段名（先 kinemesh_info 查）；静态模型省略"),
	frames: array(number().int().nonnegative()).optional().describe("帧号列表（≤64 个，按 30fps 换算 time=frame/30；必填语义在 handler 校验，缺了给三段式指引）"),
	view: record(string(), unknown()).optional().describe("完整视角对象 {\"camera\":{\"azimuth\":45,\"elevation\":15,\"distance\":3.2,\"target\":[0,1,0],\"fov\":40}}"),
	viewPreset: string().optional().describe("front / side / back / three-quarter / orbit8；与 view 二选一"),
	mode: string().optional().describe("default / solid / wireframe / skeleton / bones-overlay；**省略 = 按模型自动选**（无 mesh→skeleton；贴图解不出来→solid；有可用贴图→default）"),
	boneLabels: union([
		literal("auto"),
		literal("all"),
		number().int()
	]).optional().describe("骨骼名文字标注（B.4，与 mode:skeleton / bones-overlay 联用）：\"auto\"（第 1 批）| 批次号（1 起，stride 分批防叠）| \"all\"（全部骨骼名都画，允许重叠，调试用）"),
	width: number().int().optional().describe("宽度像素，缺省 1280"),
	height: number().int().optional().describe("高度像素，缺省 720"),
	out: string().optional().describe("PNG 输出目录；缺省 <当前工作目录>/.kinemeshtmp/run-<时间戳>-<pid>/")
}, async ({ path: rawPath, mesh, clip, frames, view, viewPreset, mode, boneLabels, width, height, out }) => {
	if (frames === void 0 || frames.length === 0) return errorResult(new KinemeshError("frames 为空：至少给一个帧号。", "frames 是整数数组，例如 \"frames\": [30]；静态模型传 [0]。"), "渲染截图");
	try {
		const loaded = await readModelFile(rawPath);
		const primary = {
			data: loaded.data,
			fileName: path.basename(loaded.abs),
			abs: loaded.abs
		};
		let meshRef;
		if (mesh !== void 0 && mesh.trim() !== "") {
			const loadedMesh = await readModelFile(mesh);
			meshRef = {
				data: loadedMesh.data,
				fileName: path.basename(loadedMesh.abs),
				abs: loadedMesh.abs
			};
		}
		const companion = await resolveCompanionForRender(primary, meshRef);
		const result = await renderScreenshots({
			data: loaded.data,
			fileName: path.basename(loaded.abs),
			companion: companion.companion,
			viewInput: {
				view,
				viewPreset,
				mode,
				clip
			},
			frames,
			width,
			height,
			outDir: out === void 0 ? void 0 : expandHome(out),
			boneLabels
		});
		return { content: [{
			type: "text",
			text: JSON.stringify({
				ok: true,
				images: result.images,
				count: result.images.length,
				warnings: [...companion.warnings, ...result.warnings],
				...result.binding === void 0 || result.binding === null ? {} : { binding: result.binding },
				hint: "用读图工具逐张查看后再给结论。"
			}, null, 2)
		}] };
	} catch (error) {
		return errorResult(error, `渲染 ${rawPath} 的截图`);
	}
});
